}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { amount: number } }}
 * @returns {{ ok: true, value: { subtotal: number, discount: number, vat: number, voucher: number, total: number } } | { ok: false, error: string }}
 */
export function invoiceTotals(invoice) {
  if (!invoice || !Array.isArray(invoice.lines) || invoice.lines.length === 0) {
    return fail('NO_LINES');
  }

  let subtotal = 0;
  let totalDiscount = 0;
  let totalVAT = 0;

  for (const line of invoice.lines) {
    const lineResult = lineTotal(line);
    if (!lineResult.ok) return lineResult;
    const gross = lineResult.value;

    subtotal += gross;

    // Calculate discount for this line
    const lineDiscount = line.discountPercent ? roundCents((gross * line.discountPercent) / 100) : 0;
    totalDiscount += lineDiscount;

    // Calculate VAT for this line (on the amount after discount)
    const net = gross - lineDiscount;
    const lineVAT = roundCents((net * line.vatRate) / 100);
    totalVAT += lineVAT;
  }

  subtotal = Math.max(0, subtotal);
  totalDiscount = Math.max(0, totalDiscount);
  totalVAT = Math.max(0, totalVAT);
  const voucherAmount = invoice.voucher ? Math.max(0, invoice.voucher.amount) : 0;
  const total = Math.max(0, subtotal - totalDiscount + totalVAT - voucherAmount);

  return ok({ subtotal, discount: totalDiscount, vat: totalVAT, voucher: voucherAmount, total });
}

/**
 * Calculate the last day of the month for a given date.
 * @param {string} date in YYYY-MM-DD format
 * @returns {string} last day of that month in YYYY-MM-DD format
 */
function getEndOfMonth(date) {
  const [year, month] = date.split('-').map(Number);
  const nextMonth = month === 12 ? 1 : month + 1;
  const nextYear = month === 12 ? year + 1 : year;
  const firstOfNextMonth = `${nextYear}-${String(nextMonth).padStart(2, '0')}-01`;
  return addDays(firstOfNextMonth, -1);
}

/**
 * Calculate the due date based on payment terms.
 * @param {string} issueDate in YYYY-MM-DD format
 * @param {string} terms NET14, NET30, or EOM
 * @returns {string} due date in YYYY-MM-DD format or null if invalid
 */
function calculateDueDate(issueDate, terms) {
  switch (terms) {
    case 'NET14':
      return addDays(issueDate, 14);
    case 'NET30':
      return addDays(issueDate, 30);
    case 'EOM':
      return getEndOfMonth(issueDate);
    default:
      return null;
  }
}

/**
 * Create an invoice from a customer and line items.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }>, terms?: string }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms: string, dueDate: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Normalize customerId
  const normalizedCustomerId = normalizeId(customerId);

  // Validate issueDate
  if (!isValidDate(issueDate)) {
    return fail('DATE_INVALID');
  }

  // Validate and calculate due date for terms
  const dueDate = calculateDueDate(issueDate, terms);
  if (dueDate === null) {
    return fail('TERMS_INVALID');
  }

  // Validate customerId and get customer
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) {
    return customerResult;
  }

  const customer = customerResult.value;

  // Validate lines
  if (!Array.isArray(lines) || lines.length === 0) {
    return fail('NO_LINES');
  }

  // Enrich and validate each line
  const enrichedLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Determine discount: explicit value wins, otherwise use tier discount
    const hasExplicitDiscount = 'discountPercent' in line;
    const discountPercent = hasExplicitDiscount ? line.discountPercent : TIER_DISCOUNTS[customer.tier];

    // Validate discountPercent
    if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
      return fail('DISCOUNT_INVALID');
    }

    // Get product
    const productResult = getProduct(line.sku);
    if (!productResult.ok) {
      return productResult;
    }

    const product = productResult.value;
    enrichedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    terms,
    dueDate,
    lines: enrichedLines,
  });
}

/**
 * Add a line to a draft invoice. If the SKU already exists, increase its quantity.
 * @param {{ status: string, customerId: string, lines: Array<{ sku: string, qty: number, name: string, unitPrice: number, vatRate: number }> }}} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} line
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function addLine(invoice, line) {
  if (!invoice || invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const { sku, qty, discountPercent } = line;

  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  // Get customer for tier discount
  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) {
    return customerResult;
  }

  const customer = customerResult.value;

  // Determine discount: explicit value wins, otherwise use tier discount
  const hasExplicitDiscount = 'discountPercent' in line;
  const discount = hasExplicitDiscount ? discountPercent : TIER_DISCOUNTS[customer.tier];

  if (typeof discount !== 'number' || discount < 0 || discount > 100) {
    return fail('DISCOUNT_INVALID');
  }

  const productResult = getProduct(sku);
  if (!productResult.ok) {
    return productResult;
  }

  const product = productResult.value;
  const newLines = invoice.lines.map((l) => ({ ...l }));
  const existingLineIndex = newLines.findIndex((l) => l.sku === sku);

  if (existingLineIndex >= 0) {
    newLines[existingLineIndex].qty += qty;
  } else {
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: discount,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {{ status: string, lines: Array<{ sku: string }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (!invoice || invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) {
    return fail('LINE_NOT_FOUND');
  }

  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  const newLines = invoice.lines
    .filter((line) => line.sku !== sku)
    .map((line) => ({ ...line }));

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Apply a voucher to a draft invoice.
 * @param {{ status: string, voucher?: any }} invoice
 * @param {{ code: string, amount: number }} voucher
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function applyVoucher(invoice, { code, amount }) {
  if (!invoice || invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  if (invoice.voucher) {
    return fail('VOUCHER_EXISTS');
  }

  if (!Number.isInteger(amount) || amount <= 0) {
    return fail('AMOUNT_INVALID');
  }

  return ok({
    ...invoice,
    voucher: { code, amount },
  });
}

/**
 * Issue a draft invoice, assigning it a number and setting status to 'issued'.
 * @param {{ status: string, issueDate: string }} invoice
 * @param {Array<string>} existingNumbers
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (!invoice || invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

